/**
 * App Router Entity Resolution
 *
 * Resolves exact and parameterized App Router pages through the same captured,
 * bounded filesystem authority used by Pages Router entity discovery.
 */
import { isCanonicalNotFoundError } from "../platform/compat/not-found-error.js";
import { withEntityResolutionAdmission, } from "../types/entities/getEntityInfo.js";
import { containsPathControlCharacters, parseRouteParameterSegment, } from "../utils/route-path-utils.js";
import { MAX_PATH_LENGTH_CHARS, MAX_ROUTE_SEGMENTS } from "../utils/constants/limits.js";
import { ROUTE_CONFLICT } from "../errors/error-registry/route.js";
import { isAbsolute, join } from "../platform/compat/path/index.js";
const APP_PAGE_EXTENSION_PRIORITY = [
    ".mdx",
    ".md",
    ".tsx",
    ".jsx",
    ".ts",
    ".js",
];
export async function getAppRouteEntity(projectDir, slug, adapter, appDirName = "app", options = {}) {
    const normalizedSlug = normalizeRouteSlug(slug);
    const normalizedAppDir = normalizeProjectDirectory(appDirName);
    if (!isBoundedPath(projectDir) ||
        normalizedSlug === null ||
        normalizedAppDir === null)
        return null;
    const appRoot = join(projectDir, normalizedAppDir);
    if (!isBoundedPath(appRoot))
        return null;
    return await withEntityResolutionAdmission(projectDir, adapter, options, async (session) => {
        const exactMatch = await tryExactMatch(appRoot, normalizedSlug, normalizedAppDir, session);
        if (exactMatch)
            return exactMatch;
        return await tryDynamicMatch(appRoot, normalizedSlug, normalizedAppDir, session);
    });
}
async function tryExactMatch(appRoot, slug, virtualRoot, session) {
    const base = slug === "" ? appRoot : join(appRoot, slug);
    if (session.hasResolveFile) {
        for (const basePath of [`${base}/page`, base]) {
            const resolvedPath = await session.resolveFile(basePath);
            if (resolvedPath === null)
                continue;
            const entity = await loadAppPage(resolvedPath, slug, appRoot, virtualRoot, session);
            if (entity)
                return entity;
        }
        return null;
    }
    for (const extension of APP_PAGE_EXTENSION_PRIORITY) {
        const entity = await loadAppPage(`${base}/page${extension}`, slug, appRoot, virtualRoot, session);
        if (entity)
            return entity;
    }
    for (const extension of APP_PAGE_EXTENSION_PRIORITY) {
        const entity = await loadAppPage(`${base}${extension}`, slug, appRoot, virtualRoot, session);
        if (entity)
            return entity;
    }
    return null;
}
async function tryDynamicMatch(appRoot, slug, virtualRoot, session) {
    const segments = slug === "" ? [] : slug.split("/");
    let currentDir = appRoot;
    for (let index = 0; index < segments.length; index++) {
        const routeDirectory = await findRouteDirectory(currentDir, segments[index], session);
        if (!routeDirectory)
            return null;
        currentDir = join(currentDir, routeDirectory.name);
        if (routeDirectory.kind === "catch-all" ||
            routeDirectory.kind === "optional-catch-all")
            break;
    }
    const directPage = await loadPageFromDirectory(currentDir, slug, appRoot, virtualRoot, session);
    if (directPage)
        return directPage;
    const optionalDirectory = await findOptionalCatchAllDirectory(currentDir, session);
    if (optionalDirectory) {
        return await loadPageFromDirectory(join(currentDir, optionalDirectory), slug, appRoot, virtualRoot, session);
    }
    return null;
}
async function findRouteDirectory(directory, segment, session) {
    const entries = await readDirectoryOrNull(directory, session);
    if (!entries)
        return null;
    const literal = entries.find((entry) => entry.isDirectory && entry.name === segment);
    if (literal)
        return { name: literal.name, kind: "literal" };
    for (const kind of ["dynamic", "catch-all", "optional-catch-all"]) {
        const candidates = entries
            .filter((entry) => entry.isDirectory)
            .map((entry) => ({
            entry,
            parameter: parseRouteParameterSegment(entry.name),
        }))
            .filter((candidate) => candidate.parameter?.kind === kind && candidate.parameter.suffix === "");
        if (candidates.length > 1) {
            throw ROUTE_CONFLICT.create({
                detail: `Multiple ${kind} App Router directories match the same route segment`,
                context: { candidateCount: candidates.length },
            });
        }
        const candidate = candidates[0];
        if (candidate)
            return { name: candidate.entry.name, kind };
    }
    return null;
}
async function findOptionalCatchAllDirectory(directory, session) {
    const entries = await readDirectoryOrNull(directory, session);
    if (!entries)
        return null;
    const candidates = entries.filter((entry) => {
        if (!entry.isDirectory)
            return false;
        const parameter = parseRouteParameterSegment(entry.name);
        return parameter?.kind === "optional-catch-all" && parameter.suffix === "";
    });
    if (candidates.length > 1) {
        throw ROUTE_CONFLICT.create({
            detail: "Multiple optional catch-all App Router directories match the same route",
            context: { candidateCount: candidates.length },
        });
    }
    return candidates[0]?.name ?? null;
}
async function readDirectoryOrNull(directory, session) {
    try {
        return await session.readDirectory(directory);
    }
    catch (error) {
        if (isCanonicalNotFoundError(error))
            return null;
        throw error;
    }
}
async function loadPageFromDirectory(directory, slug, appRoot, virtualRoot, session) {
    for (const extension of APP_PAGE_EXTENSION_PRIORITY) {
        const entity = await loadAppPage(join(directory, `page${extension}`), slug, appRoot, virtualRoot, session);
        if (entity)
            return entity;
    }
    return null;
}
async function loadAppPage(filePath, slug, appRoot, virtualRoot, session) {
    const info = await session.readEntityWithinRoot(filePath, appRoot, virtualRoot);
    if (!info)
        return null;
    const frontmatter = { ...info.entity.frontmatter };
    if (typeof frontmatter.layout === "boolean") {
        frontmatter.layout = frontmatter.layout ? "default" : "false";
    }
    return {
        ...info,
        entity: {
            ...info.entity,
            slug,
            type: "page",
            isPage: true,
            isLayout: false,
            isComponent: false,
            frontmatter,
        },
    };
}
function normalizeRouteSlug(value) {
    if (!isBoundedPath(value) || value.includes("\\"))
        return null;
    const segments = value.split("/").filter((segment) => segment !== "" && segment !== ".");
    if (segments.length > MAX_ROUTE_SEGMENTS ||
        segments.some((segment) => segment === ".."))
        return null;
    return segments.join("/");
}
function normalizeProjectDirectory(value) {
    if (!isBoundedPath(value) || value.includes("\\") || isAbsolute(value))
        return null;
    const segments = value.split("/").filter((segment) => segment !== "" && segment !== ".");
    if (segments.some((segment) => segment === ".."))
        return null;
    return segments.length === 0 ? "." : segments.join("/");
}
function isBoundedPath(value) {
    return typeof value === "string" && value.length <= MAX_PATH_LENGTH_CHARS &&
        !containsPathControlCharacters(value);
}
